from pathlib import Path
p=Path('apps/web/components/ParaguaySoyPanel.tsx')
s=p.read_text(encoding='utf-8-sig')
s=s.replace('<h2>Variables aportadas</h2>','${automaticHtml(report)}<h2>Variables aportadas por el usuario</h2>')
s=s.replace("const [report,setReport]", "const [automatic,setAutomatic]=useState<Automatic|null>(null),[autoBusy,setAutoBusy]=useState(false),[reload,setReload]=useState(0);\n const [report,setReport]")
s=s.replace(" const update=(patch:Partial<Evidence>)", " useEffect(()=>{let cancelled=false;setAutomatic(null);if(IS_DEMO||!Number.isFinite(e.lat)||!Number.isFinite(e.lon))return;setAutoBusy(true);const timer=setTimeout(()=>{void apiPost<Automatic>('/paraguay/soja/context',token,{lat:e.lat,lon:e.lon}).then(data=>{if(!cancelled)setAutomatic(data);}).catch(x=>{if(!cancelled)setAutomatic({queried_at:new Date().toISOString(),source:'Open-Meteo',variables:{},forecast:[],error:x instanceof Error?x.message:'No se pudieron cargar los datos',note:''});}).finally(()=>{if(!cancelled)setAutoBusy(false);});},700);return()=>{cancelled=true;clearTimeout(timer);};},[e.lat,e.lon,token,reload]);\n const update=(patch:Partial<Evidence>)")
s=s.replace("if(save){const row", "const submitted={...e,polygon};if(polygonText.trim()&&!polygon)throw Error('Revisá el polígono GeoJSON antes de generar el informe.');if(save){const row")
s=s.replace('{evidence:e}', '{evidence:submitted}').replace("'/paraguay/soja/evaluate',token,e)","'/paraguay/soja/evaluate',token,submitted)")
s=s.replace('<form onSubmit=', '<article className="agro-card"><h3>Datos automáticos por ubicación</h3><p>Se cargan al seleccionar el lote. Clima, humedad y temperatura de suelo son estimaciones de modelo; las mediciones de campo se ingresan debajo.</p>{autoBusy?<p role="status">Consultando clima y suelo modelado…</p>:<AutomaticData data={automatic}/>}<button disabled={autoBusy} onClick={()=>setReload(v=>v+1)}>Actualizar datos automáticos</button></article>\n <form onSubmit=')
s=s.replace('Procedencia y observaciones del relevamiento<input required minLength={3}', 'Procedencia y observaciones del relevamiento<input minLength={3}')
s=s.replace('<h4>Riesgos y acciones</h4>', '<h4>Datos automáticos incluidos en este informe</h4><AutomaticData data={report.automatic||null}/><h4>NDVI incorporado automáticamente</h4>{report.satellite?.error&&<p>{report.satellite.error}</p>}{report.satellite?.series?.length?<ul>{report.satellite.series.map(v=><li key={v.day}>{v.day}: NDVI {v.ndvi}, cobertura válida {v.valid_pixel_pct}%</li>)}</ul>:<p>Sin observaciones válidas guardadas. Revisá los límites del lote y la disponibilidad del proveedor.</p>}<h4>Riesgos y acciones</h4>')
s=s.replace('<td>{d.et0_mm??\'Sin datos\'}</td>', '<td>{d.et0_mm??\'Sin datos\'}</td>')
p.write_text(s,encoding='utf-8')
